/*! coi-serviceworker v0.1.7 - Guido Zuidhof and contributors, licensed under MIT (Optimized for HybTrans Large ONNX Streaming) */
let coepCredentialless = false;
if (typeof window === 'undefined') {
  self.addEventListener('install', () => self.skipWaiting());
  self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
  self.addEventListener('message', (e) => {
    if (!e.data) return;
    if (e.data.type === 'deregister') {
      self.registration
        .unregister()
        .then(() => self.clients.matchAll())
        .then((clients) => {
          clients.forEach((client) => client.navigate(client.url));
        });
    } else if (e.data.type === 'coepCredentialless') {
      coepCredentialless = e.data.value;
    }
  });

  self.addEventListener('fetch', function (e) {
    const r = e.request;
    if (r.cache === 'only-if-cached' && r.mode !== 'same-origin') return;

    // 針對外部大型模型庫 (HuggingFace / Xet CDN) 與雲端 API 之標準 CORS 請求直接放行由瀏覽器原生 C++ 網路層處理，
    // 避免 400MB~1.2GB 模型串流經由 ServiceWorker IPC 二次緩衝並導致 Content-Length 遺失與記憶體翻倍。
    try {
      const url = new URL(r.url);
      if (
        r.mode === 'cors' &&
        (url.hostname.endsWith('huggingface.co') ||
          url.hostname.endsWith('hf.co') ||
          url.hostname.endsWith('githubusercontent.com') ||
          url.hostname.endsWith('googleapis.com') ||
          url.hostname.endsWith('docs.google.com') ||
          url.hostname.endsWith('googleusercontent.com') ||
          url.hostname.endsWith('groq.com'))
      ) {
        return;
      }
    } catch {
      // ignore URL parse error
    }

    const s =
      coepCredentialless && r.mode === 'no-cors'
        ? new Request(r, { credentials: 'omit' })
        : r;
    e.respondWith(
      fetch(s)
        .then((res) => {
          if (res.status === 0) return res;
          const headers = new Headers(res.headers);
          headers.set(
            'Cross-Origin-Embedder-Policy',
            coepCredentialless ? 'credentialless' : 'require-corp'
          );
          if (!coepCredentialless) {
            headers.set('Cross-Origin-Resource-Policy', 'cross-origin');
          }
          headers.set('Cross-Origin-Opener-Policy', 'same-origin');
          return new Response(res.body, {
            status: res.status,
            statusText: res.statusText,
            headers,
          });
        })
        .catch((err) => console.error(err))
    );
  });
} else {
  (() => {
    const coi = {
      shouldRegister: () => true,
      shouldDeregister: () => false,
      coepCredentialless: () => !(window.chrome || window.netscape),
      doReload: () => window.location.reload(),
      quiet: true,
      ...window.coi,
    };
    const n = navigator;
    if (n.serviceWorker && n.serviceWorker.controller) {
      n.serviceWorker.controller.postMessage({
        type: 'coepCredentialless',
        value: coi.coepCredentialless(),
      });
      if (coi.shouldDeregister()) {
        n.serviceWorker.controller.postMessage({ type: 'deregister' });
      }
    }
    if (window.crossOriginIsolated === false && coi.shouldRegister()) {
      if (!window.isSecureContext) return;
      if (n.serviceWorker) {
        n.serviceWorker.register(window.document.currentScript.src).then(
          (reg) => {
            reg.addEventListener('updatefound', () => {
              coi.doReload();
            });
            if (reg.active && !n.serviceWorker.controller) {
              coi.doReload();
            }
          },
          (err) => {
            if (!coi.quiet) {
              console.error('COOP/COEP Service Worker failed to register:', err);
            }
          }
        );
      }
    }
  })();
}
